import 'package:flutter/material.dart';
import '../../../services/auth/auth_service.dart';
import '../../../services/personal_ai/opportunity_inbox_service.dart';
import '../../messenger/presentation/messenger_screen.dart';
class AurenOpportunityInboxScreen extends StatelessWidget{const AurenOpportunityInboxScreen({super.key});@override Widget build(BuildContext c){final u=FirebaseAurenAuthService().currentUserId;if(u==null)return const Scaffold(body:Center(child:Text('Sign in required')));return Scaffold(appBar:AppBar(title:const Text('AUREN Opportunity Inbox')),body:StreamBuilder<List<AurenOpportunityInboxItem>>(stream:OpportunityInboxService().watch(u),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('لا توجد فرص عامة حالياً.'));return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((x)=>Card(child:ListTile(title:Text(x.title),subtitle:Text(x.description.isEmpty?x.category:x.description),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>MessengerScreen(initialPrompt:'حلّل لي هذه الفرصة: '+x.title+' | '+x.description))))).toList());}));}}